package controllers

import javax.inject.{Inject, Singleton}
import play.api.libs.json.Json
import play.api.mvc._
import scalikejdbc.{ConnectionPool, DB}
import scalikejdbc.interpolation.Implicits._

import scala.concurrent.ExecutionContext
import scala.util.Try

/** HealthController: DB 连通性 + 进程存活（E2E 冒烟与运维探针共用） */
@Singleton
class HealthController @Inject() (val cc: ControllerComponents)(implicit ec: ExecutionContext) extends BaseController {

  override def controllerComponents: ControllerComponents = cc

  def healthz(): Action[AnyContent] = Action {
    val dbOk = Try {
      if (ConnectionPool.isInitialized()) DB.readOnly { implicit s =>
        sql"SELECT 1".map(_.int(1)).single.apply()
      }.isDefined else false
    }.getOrElse(false)
    if (dbOk) Ok(Json.obj("status" -> "ok", "db" -> "up"))
    else ServiceUnavailable(Json.obj("status" -> "degraded", "db" -> "down"))
  }
}
